from __future__ import unicode_literals
_escape_map = {ord(u'&'): u'&amp;',
 ord(u'<'): u'&lt;',
 ord(u'>'): u'&gt;'}
_escape_map_full = {ord(u'&'): u'&amp;',
 ord(u'<'): u'&lt;',
 ord(u'>'): u'&gt;',
 ord(u'"'): u'&quot;',
 ord(u"'"): u'&#x27;'}

def escape(s, quote=True):
    return s.translate(_escape_map_full) if quote else s.translate(_escape_map)
